const n = parseInt(readline());
const keys = readline().split(" ").map(Number);
const message = readline();

const hexDigits = message.replace(/[^abcdef]/g, "").split("");
const decimalValues = hexDigits.map((x) => parseInt(x, 16));
const charCodes = decimalValues.map((number, i) => number + keys[i]);
const hiddenMessage = String.fromCharCode(...charCodes);

console.log(hiddenMessage);
